function revive(value) {
  if (Array.isArray(value)) return value.map(revive);
  if (!value || typeof value !== "object") return value;
  if (value.type === "Buffer" && Array.isArray(value.data)) return Buffer.from(value.data);
  if (value.type === "Uint8Array" && Array.isArray(value.data)) return Buffer.from(value.data);
  const out = {};
  for (const [key, val] of Object.entries(value)) out[key] = revive(val);
  return out;
}

export default {
  run: async (m, socket) => {
    try {
      // Jangan bongkar botForwardedMessage. Wrapper ini diperlukan
      // untuk richResponse/HTML seperti CRM yang asli.
      const payload = revive(PAYLOAD);
      const message = proto.Message.fromObject(payload);

      await socket.relayMessage(
        m.chat,
        message,
        { messageId: Date.now().toString() }
      );
    } catch (e) {
      console.error("[CRM2PLUGIN]", e);
      await m.reply("✗ Gagal menjalankan plugin CRM: " + (e?.message || String(e)));
    }
  },

  cmd: "karate",
  alias: [],
  type: "games",
  owner: false,
  devs: false,
  premium: false,
  admin: false,
  group: false,
  botAdmin: false,
  location: "plugins/games/karate.js"
};
